import pandas as pd
def clean(df):
    df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    island_replacements = {"Dream ": "Dream", "Torgerson": "Torgersen", "Bisco": "Biscoe"}
    df['island'] = df['island'].replace(island_replacements)
    return df
def answer(df):
    counts = df.groupby('island').size().to_dict()
    return counts
